"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Tooltip: generated by UIX from the design system. Same variants and sizes as the Figma component.

const tooltipVariants = cva(
  "pointer-events-none invisible absolute z-50 whitespace-nowrap opacity-0 transition-opacity group-hover/tooltip:visible group-hover/tooltip:opacity-100 group-focus-within/tooltip:visible group-focus-within/tooltip:opacity-100 px-3 py-2 text-body-small [&>[data-arrow]]:absolute [&>[data-arrow]]:size-2 [&>[data-arrow]]:rotate-45 rounded-sm",
  {
    variants: {
      theme: {
        dark: "bg-inverse text-fg-inverse [&>[data-arrow]]:bg-inverse",
        light: "bg-surface text-fg-primary border border-line-default shadow-md [&>[data-arrow]]:bg-surface",
      },
      placement: {
        top: "bottom-full left-1/2 mb-2 -translate-x-1/2 [&>[data-arrow]]:top-full [&>[data-arrow]]:left-1/2 [&>[data-arrow]]:-mt-1 [&>[data-arrow]]:-translate-x-1/2",
        bottom: "top-full left-1/2 mt-2 -translate-x-1/2 [&>[data-arrow]]:bottom-full [&>[data-arrow]]:left-1/2 [&>[data-arrow]]:-mb-1 [&>[data-arrow]]:-translate-x-1/2",
        left: "right-full top-1/2 mr-2 -translate-y-1/2 [&>[data-arrow]]:left-full [&>[data-arrow]]:top-1/2 [&>[data-arrow]]:-ml-1 [&>[data-arrow]]:-translate-y-1/2",
        right: "left-full top-1/2 ml-2 -translate-y-1/2 [&>[data-arrow]]:right-full [&>[data-arrow]]:top-1/2 [&>[data-arrow]]:-mr-1 [&>[data-arrow]]:-translate-y-1/2",
      },
    },
    defaultVariants: {
      theme: "dark",
      placement: "top",
    },
  },
);

export interface TooltipProps
  extends Omit<React.HTMLAttributes<HTMLSpanElement>, "content">,
    VariantProps<typeof tooltipVariants> {
  content: React.ReactNode;
}

const Tooltip = React.forwardRef<HTMLSpanElement, TooltipProps>(
  ({ className, theme, placement, content, children, ...props }, ref) => {
    const id = React.useId();
    return (
      <span data-slot="tooltip" data-kind="overlay" ref={ref} className={cn("skin-quiet group/tooltip relative inline-flex", className)} {...props}>
        {React.isValidElement(children) ? React.cloneElement(children as React.ReactElement<any>, { "aria-describedby": id }) : children}
        <span id={id} role="tooltip" className={cn(tooltipVariants({ theme, placement }))}>
          {content}
          <span data-arrow="" aria-hidden />
        </span>
      </span>
    );
  },
);
Tooltip.displayName = "Tooltip";

export { Tooltip, tooltipVariants };
